/**
 * The admin Home screen in one call: today's money, members by status, dues, and check-ins by session.
For all branches it also gives each branch's day (`branches`), so the owner can compare them at a glance.
 */
export type reportsSummaryRetrieveResponse200 = {
  data: ReportsSummaryRetrieve200
  status: 200
}
    
export type reportsSummaryRetrieveResponseSuccess = (reportsSummaryRetrieveResponse200) & {
  headers: Headers;
};
;

export type reportsSummaryRetrieveResponse = (reportsSummaryRetrieveResponseSuccess)

export const getReportsSummaryRetrieveUrl = (params?: ReportsSummaryRetrieveParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/reports/summary/?${stringifiedParams}` : `/api/reports/summary/`
}

export const reportsSummaryRetrieve = async (params?: ReportsSummaryRetrieveParams, options?: RequestInit): Promise<reportsSummaryRetrieveResponse> => {
  
  return apiFetch<reportsSummaryRetrieveResponse>(getReportsSummaryRetrieveUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}





